use std::{env,fs,path::Path,process::{self,Command}};
fn usage()->!{eprintln!("usage: spore-run --image IMAGE [--mode MODE] [--root ROOT] [--snapshot-root] [--qemu QEMU] [--accel ACCEL] [--cpu CPU] [--memory MEM] [--smp N] [--vars FD] [--timings]");process::exit(2)}
fn paths(q:&str)->Vec<String>{Command::new(q).args(["-L","help"]).output().ok().map(|o|String::from_utf8_lossy(&o.stdout).split_whitespace().map(str::to_string).collect()).unwrap_or_default()}
fn find(q:&str,n:&str)->Option<String>{for d in paths(q){for p in [format!("{d}/{n}"),format!("{}/qemu/{n}",d.trim_end_matches("-firmware"))]{if Path::new(&p).is_file(){return Some(p)}}}None}
fn main(){let(mut mode,mut image,mut root,mut vars)=("filter".to_string(),None,None,None);let(mut qemu,mut accel,mut cpu,mut mem,mut smp)=(env::var("QEMU").unwrap_or_else(|_|"qemu-system-aarch64".into()),env::var("QEMU_ACCEL").unwrap_or_else(|_|"hvf".into()),env::var("QEMU_CPU").unwrap_or_else(|_|"host".into()),env::var("QEMU_MEMORY").unwrap_or_else(|_|"8G".into()),env::var("QEMU_SMP").unwrap_or_else(|_|"4".into()));let(mut timings,mut snap)=(false,false);let mut a=env::args().skip(1);while let Some(k)=a.next(){let mut v=||a.next().unwrap_or_else(||usage());match k.as_str(){"--mode"=>mode=v(),"--image"=>image=Some(v()),"--root"=>root=Some(v()),"--vars"=>vars=Some(v()),"--qemu"=>qemu=v(),"--accel"=>accel=v(),"--cpu"=>cpu=v(),"--memory"=>mem=v(),"--smp"=>smp=v(),"--timings"=>timings=true,"--snapshot-root"=>snap=true,_=>usage()}}let image=image.unwrap_or_else(||usage());if snap&&root.is_none(){usage()}let fw=find(&qemu,"edk2-aarch64-code.fd").unwrap_or_else(||"/opt/homebrew/opt/qemu/share/qemu/edk2-aarch64-code.fd".into());if let Some(v)=&vars{if !Path::new(v).exists(){let t=find(&qemu,"edk2-arm-vars.fd").or_else(||find(&qemu,"edk2-aarch64-vars.fd")).unwrap_or_else(||usage());fs::copy(t,v).unwrap_or_else(|_|usage())}}let mut q=vec![qemu,"-M".into(),"virt,gic-version=3,virtualization=off".into(),"-accel".into(),accel,"-cpu".into(),cpu,"-m".into(),mem,"-smp".into(),smp,"-global".into(),"virtio-mmio.force-legacy=false".into(),"-netdev".into(),"user,id=sporenet".into(),"-device".into(),"virtio-net-device,netdev=sporenet,mac=52:54:00:12:34:56".into(),"-boot".into(),"order=d,menu=off,strict=on".into(),"-drive".into(),format!("if=pflash,format=raw,readonly=on,file={fw}")];if let Some(v)=vars{q.extend(["-drive".into(),format!("if=pflash,format=raw,file={v}")])}if image.ends_with(".iso"){q.extend(["-cdrom".into(),image])}else{q.extend(["-drive".into(),format!("if=none,format=raw,readonly=on,file={image},id=sporeesp"),"-device".into(),"virtio-blk-device,drive=sporeesp,bootindex=0".into()])}if let Some(r)=root{q.extend(["-drive".into(),format!("if=none,format=raw,id=sporeroot,{}file={r}",if snap{"snapshot=on,"}else{""}),"-device".into(),"virtio-blk-device,drive=sporeroot".into()])}q.extend(["-serial".into(),"stdio".into(),"-display".into(),"none".into()]);process::exit(runner::harness::run(q,&mode,timings));}
